def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and s.get('last_error_kind') in ('unknown_col', 'syntax')):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_cast'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage') or ''
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema/name issue: run SHOW TABLES, then DESCRIBE the exact table name. Use backticks for identifiers with spaces or punctuation, and do not create a replacement table unless the task asks for it.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns, then relax one predicate at a time. Preserve exact casing, punctuation, spaces, percent signs, and unicode; use LIKE only when appropriate.'
    elif stage == 'text_numeric_cast':
        msg = 'Text numeric issue: when ranking, ordering, or aggregating numeric-looking TEXT columns, cast them to SIGNED or DECIMAL in SQL instead of relying on lexicographic order.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: first inspect schema and existing rows if needed, then execute the INSERT, UPDATE, or DELETE. Do not treat an empty tool result from a data-changing statement as failure by itself.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Before committing a mutation, verify the affected row or count with SELECT. For SELECT-style final answers, submit concise values or tuples rather than prose; for data-changing tasks, the database state is what matters.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (nb.get('stage') == 'ready_to_commit_candidate' or (ctx.get('state') or {}).get('mutation_attempted'))):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested values, tuples, or count.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task, but no INSERT, UPDATE, or DELETE has been executed yet. Perform the mutation and verify it before committing.'}
    return None
